import React, { useEffect, useState } from "react";
import axios from "axios";

const App = () => {
  const [certificateData, setCertificateData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Fetch certificate data from the backend
    axios
      .get("http://localhost:8080/api/certificate")
      .then((response) => {
        setCertificateData(response.data);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching certificate data:", error);
        setError("Failed to load certificate data.");
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>{error}</div>;
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Certificate of Completion</h1>
      <p style={styles.text}>This certifies that</p>
      <h2 style={styles.name}>{certificateData.studentName}</h2>
      <p style={styles.text}>has successfully completed the course</p>
      <h3 style={styles.course}>{certificateData.courseName}</h3>
      <p style={styles.date}>on {certificateData.completionDate}</p>
    </div>
  );
};

// Styles for the certificate
const styles = {
  container: {
    textAlign: "center",
    padding: "20px",
    border: "2px solid #000",
    width: "600px",
    margin: "50px auto",
    fontFamily: "Arial, sans-serif",
    backgroundColor: "#f9f9f9",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)",
  },
  title: {
    fontSize: "32px",
    color: "#333",
    marginBottom: "20px",
  },
  name: {
    fontSize: "28px",
    color: "#555",
    margin: "10px 0",
  },
  course: {
    fontSize: "24px",
    color: "#777",
    margin: "10px 0",
  },
  text: {
    fontSize: "18px",
    color: "#666",
  },
  date: {
    fontSize: "16px",
    color: "#888",
    marginTop: "20px",
  },
};

export default App;
